( function( $ ) {
	'use strict';

	/**
	 * Expands #abc to #aabbcc and adds a missing hash.
	 *
	 * The HivePress colour field's pattern only accepts six digits, and constraint validation runs
	 * before any submit handler could correct the value, so shorthand has to be expanded as it is
	 * typed rather than on submit.
	 */
	function expandHex( value ) {
		var hex = $.trim( String( value === undefined || value === null ? '' : value ) );

		if ( ! hex ) {
			return '';
		}

		if ( hex.charAt( 0 ) !== '#' ) {
			hex = '#' + hex;
		}

		if ( /^#[0-9a-fA-F]{3}$/.test( hex ) ) {
			return '#' + hex[ 1 ] + hex[ 1 ] + hex[ 2 ] + hex[ 2 ] + hex[ 3 ] + hex[ 3 ];
		}

		return hex;
	}

	$( function() {
		$( '.hp-action-bar-color-picker' ).each( function() {
			var field = $( this ),
				fallback = field.data( 'default-color' ),

				// The server-rendered attribute is the only honest record of whether a colour was ever
				// chosen. A native colour input reports #000000 when it is empty, so .val() cannot tell
				// "never set" apart from "deliberately black", and this has to be read before the picker
				// initialises.
				stored = $.trim( field.attr( 'value' ) || '' ),
				touched = false;

			// Core renders the colour field as a native swatch with no typable hex box. Site owners paste
			// brand hex codes and designers want the wheel, so the input becomes text and wpColorPicker
			// supplies the wheel alongside it.
			field.attr( 'type', 'text' );

			if ( $.fn.wpColorPicker ) {
				field.wpColorPicker( {
					defaultColor: fallback ? fallback : false,

					change: function() {
						touched = true;
					},

					clear: function() {
						touched = true;
					}
				} );

				// Iris seeds an empty input with its own starting colour, black, so merely opening the tab
				// and pressing Save would persist #000000 for every colour left blank.
				if ( ! stored ) {
					field.val( '' );
				}
			} else if ( ! stored && fallback ) {
				field.val( fallback );
			}

			field.on( 'change blur', function() {
				var expanded = expandHex( field.val() );

				if ( expanded !== field.val() ) {
					field.val( expanded );
				}
			} );

			field.on( 'keydown', function( event ) {
				if ( 13 === event.which ) {
					var expanded = expandHex( field.val() );

					if ( expanded !== field.val() ) {
						field.val( expanded );
					}
				}
			} );

			// Belt and braces for the same trap: if the admin never touched this picker and it is sitting
			// on Iris's default black over a field that was stored empty, send nothing rather than black.
			field.closest( 'form' ).on( 'submit', function() {
				if ( ! touched && ! stored && '#000000' === field.val().toLowerCase() ) {
					field.val( '' );
				}
			} );
		} );

		var toggle = $( 'input[name="hp_action_bar_enable_vendor_bar"]' ),
			vendorField = $( '[name^="hp_action_bar_vendor_items"]' ).first();

		if ( toggle.length && vendorField.length ) {
			var table = vendorField.closest( 'table.form-table' ),
				section = table.add( table.prevUntil( 'h2' ) ).add( table.prevAll( 'h2' ).first() ),
				applyToggle = function() {
					section.toggle( toggle.is( ':checked' ) );
				};

			toggle.on( 'change', applyToggle );
			applyToggle();
		}

		$( '[name^="hp_action_bar_user_items"],[name^="hp_action_bar_vendor_items"]' ).closest( '[data-component=repeater]' ).each( function() {
			var repeater = $( this ),
				applyCap = function() {
					repeater.find( '[data-add]' ).toggle( repeater.find( 'tbody tr' ).length < 5 );
				};

			repeater.on( 'click', '[data-add],[data-remove]', function() {
				window.setTimeout( applyCap, 50 );
			} );

			applyCap();
		} );
	} );
}( jQuery ) );
